def build_stabilization_jobs(args, tests, new_tests, computed_batch_size):
    # --changed-tests always auto-stabilizes the newly added tests. Small change
    # sets rerun each new test individually; very large change sets are too
    # expensive for that, so we rerun the whole new-test set a fixed number of
    # times instead.
    if args.changed_tests is not None:
        if len(new_tests) <= CHANGED_TESTS_STABILIZE_LIMIT:
            return build_per_test_rerun_jobs(new_tests)
        new_batches = list(chunked(new_tests, computed_batch_size))
        return [
            {
                "label": f"new tests bulk rerun {i + 1}/{CHANGED_TESTS_BULK_RERUNS}",
                "batches": new_batches,
                "total": len(new_tests),
            }
            for i in range(CHANGED_TESTS_BULK_RERUNS)
        ]
    if args.stabilize_tests and args.test_list is not None:
        return build_per_test_rerun_jobs(tests)
    return []


def run_stabilization_jobs(config: TestRunnerConfig, jobs):
    print(f"stabilizing tests: {len(jobs)} rerun(s)")
    any_failed = False
